inline ::flatbuffers::Offset<HYP> HYP::Pack(::flatbuffers::FlatBufferBuilder &_fbb, const HYPT* _o, const ::flatbuffers::rehasher_function_t *_rehasher) {
  (void)_rehasher;
  (void)_o;
  struct _VectorArgs { ::flatbuffers::FlatBufferBuilder *__fbb; const HYPT* __o; const ::flatbuffers::rehasher_function_t *__rehasher; } _va = { &_fbb, _o, _rehasher}; (void)_va;
  auto _CAT_IDS = _o->CAT_IDS.size() ? _fbb.CreateVectorOfStrings(_o->CAT_IDS) : 0;
  auto _SIT_IDS = _o->SIT_IDS.size() ? _fbb.CreateVectorOfStrings(_o->SIT_IDS) : 0;
  auto _NAME = _o->NAME.empty() ? 0 : _fbb.CreateString(_o->NAME);
  auto _CATEGORY = _o->CATEGORY.empty() ? 0 : _fbb.CreateString(_o->CATEGORY);
  auto _ROW_INDICATORS = _o->ROW_INDICATORS.size() ? _fbb.CreateVectorOfStrings(_o->ROW_INDICATORS) : 0;
  auto _COL_INDICATORS = _o->COL_INDICATORS.size() ? _fbb.CreateVectorOfStrings(_o->COL_INDICATORS) : 0;
  auto _MATRIX = _o->MATRIX.size() ? _fbb.CreateVector(_o->MATRIX) : 0;
  auto _SCORE = _o->SCORE.size() ? _fbb.CreateVector<::flatbuffers::Offset<Score>> (_o->SCORE.size(), [](size_t i, _VectorArgs *__va) { return CreateScore(*__va->__fbb, __va->__o->SCORE[i].get(), __va->__rehasher); }, &_va ) : 0;
  auto _ANALYSIS_METHOD = _o->ANALYSIS_METHOD.empty() ? 0 : _fbb.CreateString(_o->ANALYSIS_METHOD);
  auto _EVENT_START_TIME = _o->EVENT_START_TIME.empty() ? 0 : _fbb.CreateString(_o->EVENT_START_TIME);
  auto _EVENT_END_TIME = _o->EVENT_END_TIME.empty() ? 0 : _fbb.CreateString(_o->EVENT_END_TIME);
  return CreateHYP(
      _fbb,
      _CAT_IDS,
      _SIT_IDS,
      _NAME,
      _CATEGORY,
      _ROW_INDICATORS,
      _COL_INDICATORS,
      _MATRIX,
      _SCORE,
      _ANALYSIS_METHOD,
      _EVENT_START_TIME,
      _EVENT_END_TIME);
}

inline const HYP *GetHYP(const void *buf) {
  return ::flatbuffers::GetRoot<HYP>(buf);
}

inline const HYP *GetSizePrefixedHYP(const void *buf) {
  return ::flatbuffers::GetSizePrefixedRoot<HYP>(buf);
}

inline const char *HYPIdentifier() {
  return "$HYP";
}

inline bool HYPBufferHasIdentifier(const void *buf) {
  return ::flatbuffers::BufferHasIdentifier(
      buf, HYPIdentifier());
}

inline bool SizePrefixedHYPBufferHasIdentifier(const void *buf) {
  return ::flatbuffers::BufferHasIdentifier(
      buf, HYPIdentifier(), true);
}

template <bool B = false>
inline bool VerifyHYPBuffer(
    ::flatbuffers::VerifierTemplate<B> &verifier) {
  return verifier.template VerifyBuffer<HYP>(HYPIdentifier());
}

template <bool B = false>
inline bool VerifySizePrefixedHYPBuffer(
    ::flatbuffers::VerifierTemplate<B> &verifier) {
  return verifier.template VerifySizePrefixedBuffer<HYP>(HYPIdentifier());
}

inline void FinishHYPBuffer(
    ::flatbuffers::FlatBufferBuilder &fbb,
    ::flatbuffers::Offset<HYP> root) {
  fbb.Finish(root, HYPIdentifier());
}

inline void FinishSizePrefixedHYPBuffer(
    ::flatbuffers::FlatBufferBuilder &fbb,
    ::flatbuffers::Offset<HYP> root) {
  fbb.FinishSizePrefixed(root, HYPIdentifier());
}

inline std::unique_ptr<HYPT> UnPackHYP(
    const void *buf,
    const ::flatbuffers::resolver_function_t *res = nullptr) {
  return std::unique_ptr<HYPT>(GetHYP(buf)->UnPack(res));
}

inline std::unique_ptr<HYPT> UnPackSizePrefixedHYP(
    const void *buf,
    const ::flatbuffers::resolver_function_t *res = nullptr) {
  return std::unique_ptr<HYPT>(GetSizePrefixedHYP(buf)->UnPack(res));
}

